            Some(last_id) => {
                let next_id = self.nodes[last_id].next;
                self.nodes[id].prev = last_id;
                self.nodes[id].next = next_id;
                self.nodes[next_id].prev = id;
                self.nodes[last_id].next = id;
            }
        }

        id
    }

    fn remove_node(&mut self, id: usize) {
        let prev = self.nodes[id].prev;
        let next = self.nodes[id].next;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[id].prev_z;
        let next_z = self.nodes[id].next_z;
        if let Some(prev_z_id) = prev_z {
            self.nodes[prev_z_id].next_z = next_z;
        }
        if let Some(next_z_id) = next_z {
            self.nodes[next_z_id].prev_z = prev_z;
        }
    }

    fn calculate_bounds(&self, start: usize) -> Bounds {
        let mut min_x = self.nodes[start].x;
        let mut max_x = min_x;
        let mut min_y = self.nodes[start].y;
        let mut max_y = min_y;

        let mut id = self.nodes[start].next;
        while id != start {
            let node = &self.nodes[id];
            min_x = min_x.min(node.x);
            min_y = min_y.min(node.y);
            max_x = max_x.max(node.x);
            max_y = max_y.max(node.y);
            id = node.next;
        }

        let extent = (max_x - min_x).max(max_y - min_y);
        Bounds {
            min_x,
            min_y,
            inv_size: if extent != 0.0 { 1.0 / extent } else { 0.0 },
        }
    }

    fn earcut_linked(
        &mut self,
        start: usize,
        bounds: &Bounds,
        use_spatial_index: bool,
        indices: &mut Vec<u32>,
    ) {
        let mut ear = start;
        let mut stop = start;

        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if use_spatial_index {
                self.is_ear_hashed(ear, bounds)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                indices.push(self.nodes[prev].index);
                indices.push(self.nodes[ear].index);
                indices.push(self.nodes[next].index);

                self.remove_node(ear);
                ear = self.nodes[next].next;
                stop = ear;
                continue;
            }

            ear = next;
            if ear == stop {
                // The test program only generates a strictly convex regular
                // polygon, so the first pass always consumes the ring down to
                // two vertices and never reaches the recovery passes.
                break;
            }
        }
    }

    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if area(&self.nodes[a], &self.nodes[b], &self.nodes[c]) >= 0.0 {
            return false;
        }

        let mut p = self.nodes[self.nodes[ear].next].next;
        while p != self.nodes[ear].prev {
            if point_in_triangle(
                &self.nodes[a],
                &self.nodes[b],
                &self.nodes[c],
                &self.nodes[p],
            ) && area(
                &self.nodes[self.nodes[p].prev],
                &self.nodes[p],
                &self.nodes[self.nodes[p].next],
            ) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize, bounds: &Bounds) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if area(&self.nodes[a], &self.nodes[b], &self.nodes[c]) >= 0.0 {
            return false;
        }

        let min_tx = self.nodes[a].x.min(self.nodes[b].x).min(self.nodes[c].x);
        let min_ty = self.nodes[a].y.min(self.nodes[b].y).min(self.nodes[c].y);
        let max_tx = self.nodes[a].x.max(self.nodes[b].x).max(self.nodes[c].x);
        let max_ty = self.nodes[a].y.max(self.nodes[b].y).max(self.nodes[c].y);
        let min_z = z_order(min_tx, min_ty, bounds);
        let max_z = z_order(max_tx, max_ty, bounds);

        let mut p = self.nodes[ear].next_z;
        while let Some(id) = p {
            if self.nodes[id].z > max_z {
                break;
            }
            if id != a
                && id != c
                && point_in_triangle(&self.nodes[a], &self.nodes[b], &self.nodes[c], &self.nodes[id])
                && area(
                    &self.nodes[self.nodes[id].prev],
                    &self.nodes[id],
                    &self.nodes[self.nodes[id].next],
                ) >= 0.0
            {
                return false;
            }
            p = self.nodes[id].next_z;
        }

        let mut p = self.nodes[ear].prev_z;
        while let Some(id) = p {
            if self.nodes[id].z < min_z {
                break;
            }
            if id != a
                && id != c
                && point_in_triangle(&self.nodes[a], &self.nodes[b], &self.nodes[c], &self.nodes[id])
                && area(
                    &self.nodes[self.nodes[id].prev],
                    &self.nodes[id],
                    &self.nodes[self.nodes[id].next],
                ) >= 0.0
            {
                return false;
            }
            p = self.nodes[id].prev_z;
        }

        true
    }

    fn index_curve(&mut self, start: usize, bounds: &Bounds) {
        let mut id = start;
        loop {
            if self.nodes[id].z == 0 {
                self.nodes[id].z = z_order(self.nodes[id].x, self.nodes[id].y, bounds);
            }
            self.nodes[id].prev_z = Some(self.nodes[id].prev);
            self.nodes[id].next_z = Some(self.nodes[id].next);

            id = self.nodes[id].next;
            if id == start {
                break;
            }
        }
        self.sort_linked(start);
    }

    fn sort_linked(&mut self, start: usize) -> usize {
        let mut in_size = 1_usize;
        let mut list = Some(start);

        loop {
            let mut p = list;
            let mut tail = None;
            let mut num_merges = 0_usize;
            list = None;

            while let Some(p_id) = p {
                num_merges += 1;
                let mut q = Some(p_id);
                let mut p_size = 0_usize;

                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q.expect("q is always present while counting")].next_z;
                    if q.is_none() {
                        break;
                    }
                }

                let mut q_size = in_size;
                let mut p_cursor = Some(p_id);

                while p_size > 0 || (q_size > 0 && q.is_some()) {
                    let element;
                    if p_size == 0 {
                        element = q.expect("q-side merge requires q");
                        q = self.nodes[element].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q.is_none() {
                        element = p_cursor.expect("p-side merge requires p");
                        p_cursor = self.nodes[element].next_z;
                        p_size -= 1;
                    } else {
                        let p_element = p_cursor.expect("p-side merge requires p");
                        let q_element = q.expect("q-side merge requires q");
                        if self.nodes[p_element].z <= self.nodes[q_element].z {
                            element = p_element;
                            p_cursor = self.nodes[element].next_z;
                            p_size -= 1;
                        } else {
                            element = q_element;
                            q = self.nodes[element].next_z;
                            q_size -= 1;
                        }
                    }

                    if let Some(tail_id) = tail {
                        self.nodes[tail_id].next_z = Some(element);
                    } else {
                        list = Some(element);
                    }
                    self.nodes[element].prev_z = tail;
                    tail = Some(element);
                }

                p = q;
            }

            if let Some(tail_id) = tail {
                self.nodes[tail_id].next_z = None;
            }
            if num_merges <= 1 {
                return list.unwrap_or(start);
            }
            in_size *= 2;
        }
    }
}

fn signed_area(points: &[[f64; 2]]) -> f64 {
    let mut sum = 0.0;
    let mut previous = points.len() - 1;
    for current in 0..points.len() {
        sum += (points[previous][0] - points[current][0])
            * (points[current][1] + points[previous][1]);
        previous = current;
    }
    sum
}

fn equals(a: &Node, b: &Node) -> bool {
    a.x == b.x && a.y == b.y
}

fn area(p: &Node, q: &Node, r: &Node) -> f64 {
    (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
}

fn point_in_triangle(a: &Node, b: &Node, c: &Node, p: &Node) -> bool {
    (c.x - p.x) * (a.y - p.y) >= (a.x - p.x) * (c.y - p.y)
        && (a.x - p.x) * (b.y - p.y) >= (b.x - p.x) * (a.y - p.y)
        && (b.x - p.x) * (c.y - p.y) >= (c.x - p.x) * (b.y - p.y)
}

fn z_order(x: f64, y: f64, bounds: &Bounds) -> i32 {
    let mut x = (32767.0 * (x - bounds.min_x) * bounds.inv_size) as i32;
    let mut y = (32767.0 * (y - bounds.min_y) * bounds.inv_size) as i32;

    x = (x | (x << 8)) & 0x00FF_00FF;
    x = (x | (x << 4)) & 0x0F0F_0F0F;
    x = (x | (x << 2)) & 0x3333_3333;
    x = (x | (x << 1)) & 0x5555_5555;

    y = (y | (y << 8)) & 0x00FF_00FF;
    y = (y | (y << 4)) & 0x0F0F_0F0F;
    y = (y | (y << 2)) & 0x3333_3333;
    y = (y | (y << 1)) & 0x5555_5555;

    x | (y << 1)
}

