#[path = "src/cli.rs"]
mod cli;
#[path = "src/earcut.rs"]
mod earcut;

use std::env;
use std::io::{self, Write};

fn main() {
    let n = env::args().nth(1).map_or(1, |argument| cli::atoi_i32(&argument));
    let count = n.wrapping_mul(3);

    let mut ring = Vec::new();
    let mut i = 0_i32;
    while i < count {
        let angle = 2.0 * std::f64::consts::PI * f64::from(i) / f64::from(count);
        ring.push([angle.cos(), angle.sin()]);
        i += 1;
    }

    let polygon = vec![ring];
    let indices = earcut::earcut(&polygon);

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    for index in indices {
        write!(output, "{} ", index).expect("failed to write output");
    }
    output.flush().expect("failed to flush output");
}

